const identifyTaskDB=[{"s":"La manera de plantear algo, que decide de qué se discute.","type":"El marco"},{"s":"La señal de que el marco lo puso otro.","type":"Estarte justificando"},{"s":"La pregunta que ya trae la respuesta dentro.","type":"La pregunta cargada"},{"s":"Caro o barato, siempre respecto a algo que no se dice.","type":"El punto de comparación"},{"s":"«O esto o lo otro», con una tercera salida sin nombrar.","type":"La falsa disyuntiva"},{"s":"A quién le toca demostrar, repartido sin decirlo.","type":"La carga de la prueba"},{"s":"Convertir una decisión práctica en una prueba de bondad.","type":"El marco moral"},{"s":"La palabra que encoge lo que se pide antes de mirarlo.","type":"El «solo»"},{"s":"Decir en voz alta de qué se está hablando en realidad.","type":"Nombrar el marco"},{"s":"Aceptar la preocupación, rechazar la manera y proponer otra.","type":"Reencuadrar"}];
const classifyTaskDB=[{"w":"«¿Cuánto descuento me hace?»","gen":"Pregunta","n":"Cargada","g":"Marco ajeno","t":"Da el descuento por hecho"},{"w":"«¿Qué incluye el precio?»","gen":"Pregunta","n":"Abierta","g":"Marco propio","t":"No presupone nada"},{"w":"«Comparado con una plataforma grande»","gen":"Comparación","n":"Ajena","g":"Recorta","t":"La conclusión ya está elegida"},{"w":"«Comparado con lo que usan hoy»","gen":"Comparación","n":"Propia","g":"Amplía","t":"Mide contra lo real"},{"w":"«O gratis o nada»","gen":"Opciones","n":"Dos","g":"Falsa disyuntiva","t":"Falta la tercera salida"},{"w":"«Un piloto pagado de un mes»","gen":"Opciones","n":"Tercera","g":"Salida","t":"Más pequeña y más pronto"},{"w":"«Es solo un logo»","gen":"Tamaño","n":"Encogido","g":"El «solo»","t":"Se lee sin el solo"},{"w":"«¿Qué implica esto en un año?»","gen":"Tamaño","n":"Real","g":"Amplía","t":"Enseña lo que se pide"},{"w":"«Demuéstrame que funciona»","gen":"Prueba","n":"De tu lado","g":"Carga ajena","t":"Trabajas el doble"},{"w":"«¿Con qué lo compararías para saberlo?»","gen":"Prueba","n":"Compartida","g":"Reencuadre","t":"Devuelve la carga"}];
const completeTaskDB=[{"s":"La manera de plantear algo es el ___.","opts":["marco","guion","tono"],"ans":"marco"},{"s":"Si te estás ___, el marco lo puso otro.","opts":["justificando","riendo","callando"],"ans":"justificando"},{"s":"La pregunta que trae la respuesta dentro es ___.","opts":["cargada","larga","clara"],"ans":"cargada"},{"s":"Caro o barato depende del punto de ___.","opts":["comparación","venta","partida"],"ans":"comparación"},{"s":"El «o esto o lo otro» es una ___ disyuntiva.","opts":["falsa","buena","nueva"],"ans":"falsa"},{"s":"La prueba la enseña quien ___.","opts":["afirma","duda","paga"],"ans":"afirma"},{"s":"Decir de qué se habla de verdad es ___ el marco.","opts":["nombrar","perder","copiar"],"ans":"nombrar"},{"s":"Un marco es una verdad ___.","opts":["recortada","inventada","repetida"],"ans":"recortada"}];
const explainQuestions=[{"q":"Explica qué es un marco y por qué quien lo pone gana la conversación.","ans":"Un marco es la manera de plantear una situación, y lo que hace es decidir de qué se va a discutir y de qué no. No es un truco de palabras: es lo que consigue que unas preguntas parezcan razonables y que otras ni se le ocurran a nadie. Quien lo pone gana porque el que contesta dentro de un marco ajeno ya aceptó lo más importante sin haberlo discutido: se puede tener razón en cada argumento de una conversación y perderla entera, porque se estuvo respondiendo a la pregunta equivocada. La señal de que ha pasado es fácil de notar y cuesta aceptar: uno se está justificando. Justificarse significa que la carga de la prueba cayó de tu lado y no fuiste tú quien lo decidió."},{"q":"¿Qué es una pregunta cargada y cómo se contesta sin quedar mal?","ans":"Es la que ya trae la respuesta dentro: «¿cuánto descuento me hace?» da por hecho que hay descuento, y contestar con cualquier número acepta la premisa antes de discutirla. Lo mismo con «¿por qué cobras si es educación?», que da por hecho que lo educativo se regala. No se contesta al número: se contesta a la premisa, y se puede hacer sin sonar cortante, porque casi siempre hay debajo una preocupación legítima. «Antes del descuento, déjame decirte qué incluye el precio y qué no» acepta la conversación, cambia el marco y no ofende a nadie. La clave es que el cambio de marco va primero y el contenido después, nunca al revés."},{"q":"Explica el punto de comparación con el caso de «esto es muy básico».","ans":"Caro o barato, mucho o poco, avanzado o básico: nada de eso significa nada por sí solo, siempre es respecto a algo, y ese algo casi nunca se dice en voz alta. Quien elige la comparación ya eligió la conclusión. Cuando alguien dice que M.E.T.A.S es básico comparado con una plataforma grande, la comparación está mal puesta a propósito o por costumbre: la maestra de sexto no está eligiendo entre M.E.T.A.S y una plataforma de millones, está eligiendo entre M.E.T.A.S y la fotocopia que sacó ayer. Contra eso se mide. Y la manera de sacarlo a la luz es una pregunta corta y sin ironía: «¿comparado con qué?»."},{"q":"¿Qué es una falsa disyuntiva, cómo se reconoce y cómo se sale de ella?","ans":"Es un «o esto o lo otro» que esconde una tercera salida que no se nombró. Se reconoce por dos señales: las dos opciones que se ofrecen convienen a quien las ofrece, y ninguna de las dos es esperar. «O te adaptas a la plataforma del Estado o te quedas fuera» es una: la tercera es que las fichas funcionen al lado, en papel y sin depender de ninguna plataforma. Se sale nombrando la tercera salida, que casi siempre es más pequeña y más pronto que las dos ofrecidas: una prueba, un plazo, una parte. Y conviene proponerla con fecha, porque una tercera salida sin fecha suena a evasiva y la conversación vuelve al mismo sitio."},{"q":"Explica el marco moral y por qué es el más difícil de contestar.","ans":"El marco moral convierte una decisión práctica en una prueba de bondad: «si de verdad te importaran los niños, lo harías gratis». Es el más difícil porque cualquier respuesta dentro de él suena a mala persona: si explicas los costos, pareces interesado; si te defiendes, pareces culpable; y si aceptas, pierdes el proyecto. La salida no es discutir si a uno le importan los niños, que es justo lo que el marco quiere, sino ampliar el recorte: «me importan, y por eso quiero que esto exista el año que viene; lo gratis se apaga en marzo». Eso acepta el valor que se está invocando, lo lleva al terreno de lo que de verdad se decide y no acusa a nadie de nada."},{"q":"¿Cómo se reencuadra en tres movimientos, y por qué el primero no se puede saltar?","ans":"Primero se acepta la preocupación de fondo, que casi siempre es legítima: quien pide rebaja tiene un presupuesto de verdad, y quien dice que el material es básico teme perder el tiempo. Segundo se rechaza la manera de plantearla, nombrando el marco en voz alta y sin agresividad: «me parece que estamos discutiendo si esto se regala, y lo que yo traigo es otra cosa». Tercero se propone el marco propio, mejor en forma de pregunta, para que la otra persona entre en él por su cuenta. El primer movimiento no se puede saltar porque sin él los otros dos suenan a evasiva o a soberbia: la gente acepta un cambio de marco cuando siente que su preocupación fue oída, no cuando siente que la esquivaron."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra el concepto técnico ilustrado en cada oración. Escribe al lado de qué concepto se trata.','<strong>Ejemplo:</strong> Un solo contraejemplo basta para refutar una ley. → <span style="color:var(--jade);font-weight:700;">Falsacionismo</span>']);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y función.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Función')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Función: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function toggleAns(){ansVisible=!ansVisible;document.querySelectorAll('.tg-answer').forEach(el=>el.style.display=ansVisible?'block':'none');sfx('click');}

