function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"Una directora pregunta, con toda naturalidad: «¿y por qué cobras, si esto es educación?». No hay mala intención: para ella lo educativo se regala."},{"txt":"En una demostración, alguien dice: «comparado con una plataforma de verdad, esto es muy básico». Los demás asienten."},{"txt":"Un técnico plantea: «o te adaptas a la plataforma que va a usar el Estado, o el proyecto se queda fuera del sistema»."},{"txt":"Un posible aliado dice: «demuéstrame que esto funciona» y se queda esperando, sin decir qué habría que ver para darlo por bueno."},{"txt":"Un patrocinador pide el logotipo en la portada y lo presenta así: «es solo un logo, no cambia nada del material»."},{"txt":"Alguien cierra la conversación con: «si de verdad te importaran los niños, lo harías gratis»."},{"txt":"Una empresa propone: «nosotros ponemos la plataforma y ustedes ponen el contenido», y sigue hablando de calendarios."},{"txt":"Un maestro dice: «estás perdiendo la oportunidad de que esto llegue a todo el departamento», cuando lo que hay sobre la mesa es ceder la autoría."}];
const critCaseQuestions=["1. ¿Cuál es el marco, y qué da por hecho sin decirlo?","2. ¿Qué preocupación legítima hay debajo, que sí conviene aceptar?","3. Escribe en 3-4 frases tu reencuadre, con los tres movimientos en orden.","4. ¿Qué marco propio traerías escrito para que esto no te agarre de nuevo?"];
const critCaseGuides=["El marco casi nunca se dice: se da por hecho. Nombrar lo que da por hecho es la mitad del trabajo, y hacerlo en voz alta ya lo desarma.","Debajo de casi todo marco hay una preocupación real: un presupuesto que no alcanza, un miedo a perder el tiempo, una meta que cumplir. Aceptarla no es ceder.","Aceptar, rechazar la manera, proponer. Si se salta el primer movimiento suena a evasiva; si se salta el tercero, la conversación vuelve al marco de antes.","El marco propio se escribe en una frase: de qué va esta conversación, qué se decide hoy y qué no se discute. Quien llega sin él adopta el ajeno por educación."];

const critErrorBank=[{"txt":"\"Le expliqué durante veinte minutos todos los costos que tiene el proyecto\".","g1":"Explicar los costos es contestar dentro del marco de que hay que justificar el cobro, y cuanto más se explica, más se confirma que había algo que justificar.","g2":"Se nombra el marco y se cambia: «no cobro la educación, cobro el trabajo de hacerla; ¿cómo se sostiene esto el año que viene si no?». Después ya se puede hablar de números."},{"txt":"\"Me dijeron que era básico y me puse a enumerar funciones\".","g1":"Enumerar funciones acepta la comparación que eligió el otro, y en esa comparación se pierde siempre, porque está elegida para que se pierda.","g2":"Se pregunta «¿comparado con qué?» sin ironía. Hoy la alternativa real de esa maestra es una fotocopia, y contra eso se mide."},{"txt":"\"Como solo eran esas dos opciones, elegí la menos mala\".","g1":"Cuando las dos opciones convienen a quien las ofrece, elegir es perder despacio. Y ninguna de las dos era esperar, que casi siempre es una opción de verdad.","g2":"Se nombra la tercera salida, más pequeña y más pronto, y se propone con fecha para que no suene a evasiva."},{"txt":"\"Me pidió que demostrara que funciona y me pasé la reunión demostrando\".","g1":"La carga de la prueba cayó de un lado sin que nadie lo decidiera, y quien la carga trabaja el doble y aun así no convence.","g2":"Antes de demostrar nada: «¿qué tendrías que ver para darlo por bueno?». Eso reparte la carga y además convierte la prueba en algo alcanzable."},{"txt":"\"Era solo un logo, así que dije que sí sin pensarlo\".","g1":"El «solo» encoge la petición antes de mirarla. Y casi nunca viene solo: la siguiente petición llega con el mismo «solo» y ya con un precedente.","g2":"Se quita la palabra y se vuelve a leer: «un logotipo en la portada de todo el material». Dicho así, se decide con la cabeza y no con la cortesía."},{"txt":"\"Me dijo que si me importaran los niños lo daría gratis, y me sentí culpable\".","g1":"Ese es el marco moral funcionando: cualquier respuesta dentro de él deja mal, incluso la verdadera.","g2":"Se acepta el valor y se amplía el recorte: «me importan, y por eso quiero que esto exista el año que viene; lo gratis se apaga en marzo». No acusa a nadie y cambia el terreno."}];

const critDecisionBank=["«¿Por qué cobras si es educación?»: ¿qué contestas, y en qué orden pones los tres movimientos?","«Comparado con una plataforma de verdad esto es básico»: ¿cómo cambias el punto de comparación sin sonar defensivo?","«O te adaptas a la plataforma del Estado o te quedas fuera»: ¿cuál es la tercera salida y cómo la propones?","«Demuéstrame que funciona»: ¿qué preguntas antes de ponerte a demostrar nada?","«Es solo un logo en la portada»: ¿cómo lees la petición sin el «solo» y qué contestas?","«Si de verdad te importaran los niños sería gratis»: ¿cómo se sale de un marco moral sin quedar mal?","«Nosotros ponemos la plataforma, ustedes el contenido»: ¿qué se decidió ahí sin discutirlo?","«Estás perdiendo la oportunidad»: ¿cómo se cuenta lo mismo en términos de lo que se conserva?"];
const critDecisionGuide='La respuesta correcta en esta etapa sigue siempre el mismo orden: primero se nombra qué da por hecho el marco, que casi nunca se dijo en voz alta; después se acepta la preocupación legítima que hay debajo, porque casi siempre la hay y sin ese paso todo lo demás suena a evasiva; después se rechaza la manera de plantearlo, no a la persona; y al final se propone el marco propio, mejor en forma de pregunta, para que la otra parte entre en él por su cuenta. Si al terminar la conversación uno se ha pasado el rato justificándose, el marco era ajeno y la discusión estaba perdida desde la primera frase, por mucha razón que se tuviera en cada argumento.';

const critCompareBank=[{"a":"«¿Comparado con qué? Hoy la maestra usa una fotocopia».","b":"Enumerar las funciones que sí tiene el material.","ga":"Caso A: saca a la luz el punto de comparación y devuelve la conversación al terreno real, donde el material gana.","gb":"Caso B: acepta una comparación elegida para perder, y cuanto más se enumera, más pequeño parece."},{"a":"«¿Qué tendrías que ver para darlo por bueno?».","b":"Ponerse a enseñar todos los datos que se tengan.","ga":"Caso A: reparte la carga de la prueba y convierte una exigencia infinita en una lista concreta.","gb":"Caso B: carga con una prueba que nadie definió, así que nunca es suficiente por mucho que se enseñe."},{"a":"«Me importan, y por eso quiero que exista el año que viene».","b":"«Claro que me importan, mira todo lo que llevo hecho».","ga":"Caso A: acepta el valor invocado y amplía el recorte hacia lo que de verdad se está decidiendo.","gb":"Caso B: se queda dentro del marco moral, donde defenderse ya parece una confesión."},{"a":"«Hay una tercera: que las fichas funcionen al lado, en papel».","b":"Elegir la menos mala de las dos opciones ofrecidas.","ga":"Caso A: nombra la salida que la disyuntiva ocultaba, y suele ser más pequeña y más pronto.","gb":"Caso B: elegir entre dos opciones que convienen al otro es perder despacio y con permiso."}];

const critCauseBank=[{"cause":"Se contesta al contenido antes de mirar el marco.","guide":"Se puede tener razón en cada argumento y perder la conversación entera, porque se estuvo respondiendo a la pregunta equivocada."},{"cause":"Se acepta el punto de comparación que eligió el otro.","guide":"La conclusión ya estaba decidida cuando se eligió la comparación, así que la discusión solo sirve para confirmarla."},{"cause":"Se elige entre las dos opciones que ofrecieron.","guide":"Cuando las dos convienen a quien las ofrece, elegir es perder despacio. Y casi nunca está la de esperar, que suele ser la mejor."},{"cause":"Se carga con una prueba que nadie definió.","guide":"Sin saber qué habría que ver para darlo por bueno, ninguna cantidad de datos alcanza, y quien demuestra queda siempre en deuda."},{"cause":"Se acepta un «solo» sin quitarle la palabra.","guide":"La petición entra encogida y crea un precedente, así que la siguiente llega con el mismo «solo» y con la puerta ya abierta."},{"cause":"Se entra en el marco moral a defenderse.","guide":"Dentro de ese marco cualquier respuesta deja mal, incluso la verdadera, porque el terreno ya no es la decisión sino el carácter."}];
const critEffectBank=[{"effect":"La conversación sobre el precio duró tres minutos y terminó bien.","guide":"Se nombró el marco al principio: no se cobra la educación, se cobra el trabajo de hacerla. Después los números fueron fáciles."},{"effect":"La palabra «básico» no volvió a aparecer.","guide":"Se preguntó «¿comparado con qué?» y quedó claro que la alternativa real era una fotocopia, no una plataforma de millones."},{"effect":"Apareció una opción que nadie había puesto sobre la mesa.","guide":"Se buscó la tercera salida en vez de elegir entre las dos ofrecidas, y era más pequeña y más pronto que las dos."},{"effect":"La demostración duró diez minutos y bastó.","guide":"Antes de enseñar nada se preguntó qué habría que ver para darlo por bueno, así que se enseñó exactamente eso."},{"effect":"El logotipo se aceptó y la autoría no se tocó.","guide":"Se leyó la petición sin el «solo», así que se vio lo que se pedía de verdad y se pudo negociar pieza por pieza."},{"effect":"Nadie salió de la reunión sintiéndose acusado.","guide":"El reencuadre empezó aceptando la preocupación de fondo, que es lo que permite cambiar de marco sin que parezca una esquiva."}];

function genEvalCrit(){
  sfx('click');
  _injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});const _sC=document.getElementById('evalCritFormaSel');if(_sC&&parseInt(_sC.value,10))evalCritFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_sC.value,10)));const cf=evalCritFormNum;window._currentEvalCritForm=cf;const rngC=_evalRng(200000+cf);evalCritFormNum=(evalCritFormNum%EVAL_FORMAS)+1;_injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`🧠 Quién puso el marco · Forma ${cf} · Marcos, quien pone el marco gana la conversación · Ruta de la Persuasión`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_rotaF(critCaseBank,cf);
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. Simulacro de Presión: la interpelación <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_rotaF(critErrorBank,cf);
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_rotaF(critDecisionBank,cf);
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones bajo presión <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">¿Cuál es el marco, qué preocupación legítima hay debajo y cómo lo reencuadras en tres movimientos? Explica por qué tu salida es mejor que contestar dentro del marco o que rechazar de plano.</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_rotaF(critCompareBank,cf);
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Cuál de las dos respuestas cambia el terreno de la conversación? 2. ¿Por qué la otra confirma el marco ajeno?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pickF(critCauseBank,2,rngC),effects=_pickF(critEffectBank,3,rngC);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>🧮 Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0–20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 Quién puso el marco: '+total+'/100');}
  else showToast('🧮 Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
function printEvalCrit(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  const forma=window._currentEvalCritForm||1;const d=window._evalCritData;
  const lines=(n)=>Array(n).fill('<div class="ln"></div>').join('');
  let s1=`<div class="sec-title"><span>I. Simulacro de Presión: la interpelación</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.kase.txt}</p>`;
  critCaseQuestions.forEach(q=>{s1+=`<p class="crit-print-q">${q}</p>${lines(1)}`;});
  let s2=`<div class="sec-title"><span>II. Corrige el error</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.err.txt}</p><p class="crit-print-q">Identifica dos errores y corrígelos con tus propias palabras:</p><p class="crit-print-q"><strong>Error 1:</strong></p>${lines(1)}<p class="crit-print-q"><strong>Error 2:</strong></p>${lines(1)}`;
  let s3=`<div class="sec-title"><span>III. Toma de decisiones bajo presión</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">¿Cuál es el marco, qué preocupación legítima hay debajo y cómo lo reencuadras en tres movimientos? Explica por qué tu salida es mejor que contestar dentro del marco o que rechazar de plano.</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Cuál de las dos respuestas cambia el terreno de la conversación? 2. ¿Por qué la otra confirma el marco ajeno?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
  d.causes.forEach(it=>{ceTbl+=`<tr><td>${it.cause}</td><td></td></tr>`;});
  d.effects.forEach(it=>{ceTbl+=`<tr><td></td><td>${it.effect}</td></tr>`;});
  ceTbl+='</table>';
  let s5=`<div class="sec-title"><span>V. Análisis de causas y efectos</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div>${ceTbl}`;
  let pR='';
  pR+=`<div class="p-sec"><div class="p-ttl">I. Caso</div>${critCaseQuestions.map((q,i)=>`<div class="p-crit-line"><strong>${i+1}.</strong> ${critCaseGuides[i]}</div>`).join('')}</div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">II. Corrige el error</div><div class="p-crit-line"><strong>Error 1:</strong> ${d.err.g1}</div><div class="p-crit-line"><strong>Error 2:</strong> ${d.err.g2}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">III. Toma de decisiones</div><div class="p-crit-line">${critDecisionGuide}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">IV. Comparación</div><div class="p-crit-line"><strong>Caso A:</strong> ${d.cmp.ga}</div><div class="p-crit-line"><strong>Caso B:</strong> ${d.cmp.gb}</div><div class="p-crit-line">${d.cmp.gr}</div></div>`;
  pR+=`<div class="p-sec" style="grid-column:1/-1;"><div class="p-ttl">V. Causas y efectos</div>${d.causes.map(it=>`<div class="p-crit-line"><strong>Causa:</strong> ${it.cause} → <strong>Efecto:</strong> ${it.guide}</div>`).join('')}${d.effects.map(it=>`<div class="p-crit-line"><strong>Efecto:</strong> ${it.effect} → <strong>Causa:</strong> ${it.guide}</div>`).join('')}</div>`;
  const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>Quién puso el marco Marcos, quien pone el marco gana la conversación · Ruta de la Persuasión · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.1rem 0.4rem;margin:0.2rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #3b3a86;background:#ece9fb;color:#3b3a86;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#3b3a86;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:50px;border-bottom:1.5px solid #3b3a86;height:12px;}.obt-pct{white-space:nowrap;}.crit-print-scenario{font-size:10.5pt;background:#ece9fb;border-left:3px solid #3b3a86;padding:0.2rem 0.5rem;margin:0.1rem 0 0.2rem;line-height:1.3;}.crit-print-q{font-size:10pt;font-weight:600;margin:0.15rem 0 0.08rem;line-height:1.25;}.ln{border-bottom:1px solid #111;min-height:12px;margin-bottom:2px;}.crit-compare-print-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem;margin:0.15rem 0;}.crit-compare-print-box{font-size:9.5pt;background:#ece9fb;border-radius:4px;padding:0.25rem 0.4rem;line-height:1.25;}.crit-print-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-top:0.15rem;}.crit-print-tbl th,.crit-print-tbl td{border:1px solid #999;padding:0.3rem 0.45rem;text-align:left;height:30px;vertical-align:middle;}.crit-print-tbl th{background:#ece9fb;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.3rem 0.45rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.18rem;}.p-crit-line{font-size:7.5pt;color:#007a00;margin-bottom:0.18rem;line-height:1.35;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.2rem;padding:0.1rem 0;color:#3b3a86;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #3b3a86;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Competencial · Quién puso el marco · Marcos, quien pone el marco gana la conversación · Ruta de la Persuasión · Etapa 3 · Psicología y Persuasión</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Institución:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · 5 secciones de 20 puntos</p></div>${s1}${s2}${s3}${s4}${s5}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: Quién puso el marco · Marcos, quien pone el marco gana la conversación · Ruta de la Persuasión · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 5 secciones × 20 pts c/u, respuesta abierta, usar como guía de corrección</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}

