const timelineData=[{"y":"1","icon":"🖼️","label":"Qué es el marco","text":"La <strong>manera de plantear algo</strong>, que decide de qué se discute. <strong>Decide:</strong> la conversación entera. <strong>Se rompe:</strong> al contestar el contenido sin mirarlo. <strong>En M.E.T.A.S:</strong> «¿por qué cobras si es educación?» ya dio por hecho que se regala."},{"y":"2","icon":"🚨","label":"La señal","text":"Notar que <strong>te estás justificando</strong>. <strong>Decide:</strong> si te das cuenta a tiempo. <strong>Se rompe:</strong> cuando justificarse se confunde con explicar bien. <strong>En M.E.T.A.S:</strong> veinte minutos enumerando costos son veinte minutos dentro del marco ajeno."},{"y":"3","icon":"❓","label":"La pregunta cargada","text":"La que <strong>ya trae la respuesta dentro</strong>. <strong>Decide:</strong> qué se da por aceptado. <strong>Se rompe:</strong> al contestar con un número. <strong>En M.E.T.A.S:</strong> «¿cuánto descuento me hace?» se contesta con lo que incluye el precio, no con una cifra."},{"y":"4","icon":"📐","label":"La comparación","text":"Caro o básico, <strong>siempre respecto a algo</strong> que no se dijo. <strong>Decide:</strong> la conclusión. <strong>Se rompe:</strong> al aceptar la comparación ajena. <strong>En M.E.T.A.S:</strong> la alternativa real de la maestra es una fotocopia."},{"y":"5","icon":"🚪","label":"La disyuntiva","text":"Dos opciones que <strong>convienen a quien las ofrece</strong>. <strong>Decide:</strong> si aparece la tercera salida. <strong>Se rompe:</strong> al elegir la menos mala. <strong>En M.E.T.A.S:</strong> las fichas en papel funcionan al lado de cualquier plataforma."},{"y":"6","icon":"⚖️","label":"La carga","text":"A quién le toca <strong>demostrar</strong>, repartido sin decirlo. <strong>Decide:</strong> quién trabaja el doble. <strong>Se rompe:</strong> al demostrar sin preguntar qué basta. <strong>En M.E.T.A.S:</strong> «¿qué tendrías que ver para darlo por bueno?»."},{"y":"7","icon":"🔄","label":"El reencuadre","text":"<strong>Aceptar, rechazar la manera, proponer.</strong> <strong>Decide:</strong> si se cambia de terreno sin pelear. <strong>Se rompe:</strong> al saltarse el primer paso. <strong>En M.E.T.A.S:</strong> sin aceptar la preocupación, todo lo demás suena a evasiva."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ===================== SIMULACIÓN: MÉTODO DE POPPER =====================
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(nombraste){sfx(nombraste?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(nombraste){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">🏷️</span><span class="ms-text"><strong>Nombraste el marco:</strong> «me parece que estamos discutiendo si esto se regala, y lo que yo traigo es otra cosa». Nadie se ofendió, porque no acusaste a nadie: describiste la conversación.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🔄</span><span class="ms-text"><strong>Y cambió el terreno:</strong> «no cobro la educación, cobro el trabajo de hacerla; ¿cómo se sostiene el año que viene si no?». A partir de ahí se habló de números, que es donde tú tienes las respuestas.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">🗯️</span><span class="ms-text"><strong>Te pusiste a explicar los costos:</strong> hospedaje, impresión, las horas. Todo cierto, y todo dicho desde dentro del marco de que había algo que justificar.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">📉</span><span class="ms-text"><strong>Y cuanto más explicabas, peor:</strong> veinte minutos justificándote confirman que el cobro necesitaba defensa. Se puede tener razón en cada cifra y perder la conversación entera.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

// ===================== LABORATORIO DE CONCEPTOS =====================
const parteData={"marco":{"nombre":"El marco","icon":"🖼️","estructura":{"title":"Qué es","info":"• La <strong>manera de plantear</strong> una situación<br>• Decide de qué se discute y de qué no<br>• No es una mentira: es una <strong>verdad recortada</strong>"},"funcion":{"title":"Cómo se detecta","info":"• Por la señal: <strong>te estás justificando</strong><br>• Preguntándose qué da por hecho la frase sin decirlo<br>• Y mirando a quién le conviene que se discuta eso"},"enfermedades":{"title":"Dónde se pierde","info":"• Al contestar el contenido antes de mirar el marco<br>• Al confundir justificarse con explicar bien<br>• Al creer que tener razón en cada argumento basta"},"cuidados":{"title":"Cómo está en M.E.T.A.S","info":"• El marco que más aparece: <strong>lo educativo se regala</strong><br>• Y el que más caro sale: <strong>quién es el dueño</strong> de lo que se haga en conjunto<br>• Los dos se desarman nombrándolos"}},"referencia":{"nombre":"El punto de comparación","icon":"📐","estructura":{"title":"Qué es","info":"• Caro, barato, básico o avanzado: <strong>siempre respecto a algo</strong><br>• Ese algo casi nunca se dice en voz alta<br>• Quien elige la comparación ya eligió la conclusión"},"funcion":{"title":"Cómo se detecta","info":"• Con una pregunta corta y sin ironía: <strong>«¿comparado con qué?»</strong><br>• Buscando cuál es la alternativa <strong>real</strong> de quien decide<br>• Y diciendo la propia comparación antes de que la pongan"},"enfermedades":{"title":"Dónde se pierde","info":"• Al enumerar funciones para defenderse<br>• Al aceptar que el rival es una plataforma grande<br>• Al comparar con lo que se quiere ser, no con lo que hay"},"cuidados":{"title":"Cómo está en M.E.T.A.S","info":"• La alternativa real de la maestra de sexto no es una plataforma: es <strong>la fotocopia de ayer</strong> o nada<br>• Contra eso se mide, y contra eso el material gana"}},"prueba":{"nombre":"La carga de la prueba","icon":"⚖️","estructura":{"title":"Qué es","info":"• A quién le toca <strong>demostrar</strong> lo que se afirma<br>• Es el marco más invisible: se reparte sin decirlo<br>• Regla justa: <strong>la enseña quien afirma</strong>"},"funcion":{"title":"Cómo se detecta","info":"• Mirando quién está trabajando en la conversación<br>• Antes de demostrar nada: <strong>«¿qué tendrías que ver para darlo por bueno?»</strong><br>• Eso convierte una exigencia infinita en una lista"},"enfermedades":{"title":"Dónde se pierde","info":"• Al ponerse a enseñar datos sin saber cuáles bastan<br>• Al aceptar demostrar algo que nadie ha definido<br>• Al confundir «probar que sirve» con «probar que es lo mejor»"},"cuidados":{"title":"Cómo está en M.E.T.A.S","info":"• Lo que sí se puede enseñar: la <strong>ficha impresa</strong> y la aplicación abierta en un teléfono<br>• Y lo que hay que decir uno mismo: falta que lo revise un maestro de fuera"}},"reencuadre":{"nombre":"El reencuadre","icon":"🔄","estructura":{"title":"Qué es","info":"• Cambiar el marco <strong>sin pelear</strong><br>• Tres movimientos: aceptar, rechazar la manera, proponer<br>• El primero no se puede saltar"},"funcion":{"title":"Cómo se detecta","info":"• Se acepta la <strong>preocupación de fondo</strong>, que casi siempre es real<br>• Se nombra el marco en voz alta y sin agresividad<br>• Se propone el propio, mejor <strong>en forma de pregunta</strong>"},"enfermedades":{"title":"Dónde se pierde","info":"• Al saltarse el primer paso: entonces suena a evasiva<br>• Al reencuadrar acusando a la persona en vez de a la manera<br>• Al no proponer nada, que devuelve la conversación al marco de antes"},"cuidados":{"title":"Cómo está en M.E.T.A.S","info":"• El reencuadre de la casa, ya probado: <strong>«no cobro la educación, cobro el trabajo de hacerla»</strong><br>• Y el que hace falta tener escrito: <strong>de qué va esta conversación y qué se decide hoy</strong>"}}};
let labParte='marco',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`🦉 Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue estudiando tu sistema!','¡Muy buen trabajo!','¡Excelente gestor en formación!','¡Sabes por dónde se mueve esto!','¡Estratega institucional!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='🖼️ ¡'+name+' completó la Etapa 3 de la Ruta de la Persuasión (Marcos, quien pone el marco gana la conversación)! 🏅 Progreso: '+pct+'% · ⚙️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

